public extension RivetDeviceRouter {
    func registerGeneratedBackend(_ api: RivetAPI) throws {
        try register(RivetDeviceRequests.ExplainRoute.self) { request in
            try await api.explain_route(profileJson: request.profileJson, domain: request.domain, ip: request.ip, port: request.port, network: request.network)
        }
        try register(RivetDeviceRequests.CompileEngineConfig.self) { request in
            try await api.compile_engine_config(profileJson: request.profileJson)
        }
        try register(RivetDeviceRequests.EngineDryRun.self) { request in
            try await api.engine_dry_run(profileJson: request.profileJson, socksPort: request.socksPort)
        }
        try register(RivetDeviceRequests.EngineSessionStart.self) { request in
            try await api.engine_session_start(profileJson: request.profileJson, socksPort: request.socksPort)
        }
        try register(RivetDeviceRequests.EngineSessionStop.self) { request in
            try await api.engine_session_stop(sessionId: request.sessionId)
        }
        try register(RivetDeviceRequests.EngineSessionEvents.self) { request in
            try await api.engine_session_events(sessionId: request.sessionId)
        }
        try register(RivetDeviceRequests.DiagnoseRoute.self) { request in
            try await api.diagnose_route(profileJson: request.profileJson, domain: request.domain, ip: request.ip, port: request.port, network: request.network, redact: request.redact)
        }
        try register(RivetDeviceRequests.LibraryList.self) { request in
            try await api.library_list(root: request.root)
        }
        try register(RivetDeviceRequests.LibraryReadProfile.self) { request in
            try await api.library_read_profile(root: request.root, profileId: request.profileId)
        }
        try register(RivetDeviceRequests.LibraryImportPreview.self) { request in
            try await api.library_import_preview(root: request.root, name: request.name, text: request.text)
        }
        try register(RivetDeviceRequests.LibraryImportCommit.self) { request in
            try await api.library_import_commit(root: request.root, name: request.name, description: request.description, text: request.text)
        }
        try register(RivetDeviceRequests.LibraryUpdateRules.self) { request in
            try await api.library_update_rules(root: request.root, profileId: request.profileId, rulesText: request.rulesText)
        }
        try register(RivetDeviceRequests.LibraryDeleteProfile.self) { request in
            try await api.library_delete_profile(root: request.root, profileId: request.profileId)
        }
        try register(RivetDeviceRequests.LibrarySetActive.self) { request in
            try await api.library_set_active(root: request.root, profileId: request.profileId)
        }
        try register(RivetDeviceRequests.LibraryPatchPreview.self) { request in
            try await api.library_patch_preview(root: request.root, profileId: request.profileId, target: request.target, policy: request.policy)
        }
        try register(RivetDeviceRequests.LibraryPatchApply.self) { request in
            try await api.library_patch_apply(root: request.root, profileId: request.profileId, target: request.target, policy: request.policy)
        }
        try register(RivetDeviceRequests.LibraryRestoreProfile.self) { request in
            try await api.library_restore_profile(root: request.root, profileJson: request.profileJson)
        }
    }
}

#if canImport(RivetDeviceAppleTransport)
import RivetDeviceAppleTransport

// Typed network-channel surface for the same `device-rpcs` allowlist as
// RivetDeviceClient above (issue #489): each allowlisted request becomes
// call("<name>", [RivetValue…]) with positional typed arguments. Bytes
// results are returned raw — decode them exactly like the desktop host
// does. The gateway scope check stays authoritative; this surface is a
// usability aid, not an authorization decision.
private func rivetRVT1Data(_ value: RivetValue) throws -> Data {
    guard case .bytes(let data) = value else {
        throw RivetGeneratedError.typeMismatch("bytes")
    }
    return data
}

private func rivetRVT1String(_ value: RivetValue) throws -> String {
    guard case .string(let value) = value else {
        throw RivetGeneratedError.typeMismatch("string")
    }
    return value
}

private func rivetRVT1Int64(_ value: RivetValue) throws -> Int64 {
    guard case .int64(let value) = value else {
        throw RivetGeneratedError.typeMismatch("int64")
    }
    return value
}

private func rivetRVT1Bool(_ value: RivetValue) throws -> Bool {
    guard case .bool(let value) = value else {
        throw RivetGeneratedError.typeMismatch("bool")
    }
    return value
}

public extension RivetDeviceAppleRVT1Client {
    func diagnose_route(profileJson: String, domain: String, ip: String, port: Int64, network: String, redact: Bool) async throws -> String {
        try rivetRVT1String(try await call("diagnose-route", arguments: [.string(profileJson), .string(domain), .string(ip), .int64(port), .string(network), .bool(redact)]))
    }
    func library_read_profile(root: String, profileId: String) async throws -> String {
        try rivetRVT1String(try await call("library-read-profile", arguments: [.string(root), .string(profileId)]))
    }
}

